package dev.underthebedrock.horror;
import dev.underthebedrock.UnderTheBedrockPlugin;import org.bukkit.configuration.ConfigurationSection;import org.bukkit.configuration.file.YamlConfiguration;
import java.io.File;import java.io.IOException;import java.util.*;
public final class PlayerHorrorMemoryStore {
 private final UnderTheBedrockPlugin plugin;private final File file;private final YamlConfiguration data;
 public PlayerHorrorMemoryStore(UnderTheBedrockPlugin p){plugin=p;file=new File(p.getDataFolder(),"player-horror-memory.yml");data=YamlConfiguration.loadConfiguration(file);}
 public PlayerHorrorMemory load(UUID id){String root=id.toString();ConfigurationSection s=data.getConfigurationSection(root);PlayerHorrorMemory m=new PlayerHorrorMemory();if(s==null)return m;Map<EntityArchetype,Integer> counts=new EnumMap<>(EntityArchetype.class);ConfigurationSection entities=s.getConfigurationSection("entities");if(entities!=null)for(EntityArchetype a:EntityArchetype.values()){int n=Math.max(0,entities.getInt(a.name()));if(n>0)counts.put(a,n);}Set<String> clues=new HashSet<>(s.getStringList("discovered-clues"));m.restore(s.getDouble("tension"),s.getDouble("provocation"),s.getLong("last-occurrence-at"),s.getLong("last-severe-occurrence-at"),s.getLong("last-chat"),s.getLong("last-entity-encounter-at"),s.getLong("encounters"),s.getLong("distance-travelled"),s.getString("last-occurrence","none"),counts,clues,s.getString("last-clue-id","none"),s.getLong("last-clue-at"),new LinkedHashSet<>(s.getStringList("discovered-lore")),new LinkedHashSet<>(s.getStringList("heard-recordings")));return m;}
 public void save(UUID id,PlayerHorrorMemory m){String r=id.toString();data.set(r+".tension",m.tension());data.set(r+".provocation",m.provocation());data.set(r+".last-occurrence",m.lastOccurrence());data.set(r+".last-occurrence-at",m.lastOccurrenceAt());data.set(r+".last-severe-occurrence-at",m.lastSevereOccurrenceAt());data.set(r+".last-chat",m.lastChatAt());data.set(r+".last-entity-encounter-at",m.lastEntityEncounterAt());data.set(r+".encounters",m.encounters());data.set(r+".distance-travelled",m.distanceTravelled());data.set(r+".discovered-clues",m.discoveredClues().stream().sorted().toList());data.set(r+".last-clue-id",m.lastClueId());data.set(r+".last-clue-at",m.lastClueAt());data.set(r+".discovered-lore",m.discoveredLore().stream().sorted().toList());data.set(r+".heard-recordings",m.heardRecordings().stream().sorted().toList());for(EntityArchetype a:EntityArchetype.values())data.set(r+".entities."+a.name(),m.entityEncounters().getOrDefault(a,0));try{if(!file.getParentFile().exists()&&!file.getParentFile().mkdirs()){plugin.getLogger().warning("Could not create horror memory directory.");return;}data.save(file);}catch(IOException e){plugin.getLogger().severe("Could not save horror memory: "+e.getMessage());}}
}